import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 8;

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";

const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Back_Dark.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ============================================================
// SCENE 1: Hero headline — "Actors — built for agents"
// ============================================================
const SCENE_ONE_DURATION = 75;

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const HERO_LEAD = "Actors";
  const HERO_DASH = "—";
  const HERO_TAIL_LEAD = "built for";
  const HERO_HIGHLIGHT = "agents";

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const heroIn = springIn(frame, vfps, 8, "SNAPPY");
  const tailIn = springIn(frame, vfps, 18, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 26, "LIQUID");
  const subIn = springIn(frame, vfps, 38, "GENTLE");

  const eyebrowY = interpolate(eyebrowIn, [0, 1], [12, 0]);
  const heroY = interpolate(heroIn, [0, 1], [44, 0]);
  const heroScale = interpolate(heroIn, [0, 1], [0.94, 1]);
  const heroBlur = interpolate(heroIn, [0, 1], [10, 0]);
  const tailY = interpolate(tailIn, [0, 1], [28, 0]);
  const subY = interpolate(subIn, [0, 1], [16, 0]);

  const driftY = ambientDrift(frame, 2.5, 110, "hero-drift");
  const driftX = ambientDrift(frame, 1.5, 140, "hero-drift-x");
  const eyebrowDrift = ambientDrift(frame, 1, 80, "eyebrow");

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(120% 80% at 18% 25%, ${COLORS.card} 0%, ${COLORS.bg} 60%)`,
        fontFamily: FONT_MARKETING,
      }}
    >
      <Background />

      {/* Eyebrow — top-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "16%",
          opacity: eyebrowIn,
          transform: `translate(${eyebrowDrift}px, ${eyebrowY}px)`,
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        / new
      </div>

      {/* Hero stack — left anchored */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "30%",
          maxWidth: "82%",
          transform: `translate(${driftX}px, ${driftY}px)`,
        }}
      >
        <div
          style={{
            fontFamily: FONT_MARKETING,
            fontSize: 196,
            fontWeight: 600,
            color: COLORS.text,
            lineHeight: 0.96,
            letterSpacing: "-0.035em",
            opacity: heroIn,
            transform: `translateY(${heroY}px) scale(${heroScale})`,
            filter: `blur(${heroBlur}px)`,
          }}
        >
          {HERO_LEAD}
          <span style={{ color: COLORS.textMuted, marginLeft: 18, marginRight: 18 }}>
            {HERO_DASH}
          </span>
        </div>

        <div
          style={{
            marginTop: 8,
            fontFamily: FONT_MARKETING,
            fontSize: 196,
            fontWeight: 600,
            color: COLORS.text,
            lineHeight: 0.96,
            letterSpacing: "-0.035em",
            opacity: tailIn,
            transform: `translateY(${tailY}px)`,
            display: "flex",
            alignItems: "baseline",
            flexWrap: "wrap",
            gap: 24,
          }}
        >
          <span>{HERO_TAIL_LEAD}</span>
          <span
            style={{
              fontFamily: FONT_MARKETING,
              background: COLORS.orangeTint,
              borderBottom: `4px solid ${COLORS.orange}`,
              padding: "0 16px",
              borderRadius: 10,
              color: COLORS.text,
              clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
              display: "inline-block",
            }}
          >
            {HERO_HIGHLIGHT}
          </span>
        </div>

        <div
          style={{
            marginTop: 48,
            fontFamily: FONT_PRIMARY,
            fontSize: 36,
            fontWeight: 400,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.35,
            maxWidth: 720,
            opacity: subIn,
            transform: `translateY(${subY}px)`,
          }}
        >
          Composable web actions, ready for any AI agent.
        </div>
      </div>

      {/* Subtle orange dot field — bottom-right */}
      <div
        style={{
          position: "absolute",
          right: "6%",
          bottom: "8%",
          width: 280,
          height: 120,
          opacity: 0.45,
          backgroundImage: `radial-gradient(${COLORS.orange} 1.3px, transparent 1.6px)`,
          backgroundSize: "14px 14px",
          maskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.9), transparent)",
          WebkitMaskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.9), transparent)",
        }}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 2: Flow diagram — Trigger → Actor → Output
// ============================================================
const SCENE_TWO_DURATION = 90;

type FlowNode = {
  label: string;
  caption: string;
  icon: "trigger" | "actor" | "output";
};

const NODES: FlowNode[] = [
  { label: "Trigger", caption: "Webhook, schedule, agent call", icon: "trigger" },
  { label: "Actor", caption: "Your code, packaged & versioned", icon: "actor" },
  { label: "Output", caption: "Structured data, anywhere", icon: "output" },
];

const NodeIcon: React.FC<{ kind: FlowNode["icon"]; size: number; progress: number }> = ({
  kind,
  size,
  progress,
}) => {
  const stroke = COLORS.orange;
  const sw = 2.6;
  const op = progress;

  if (kind === "trigger") {
    return (
      <svg width={size} height={size} viewBox="0 0 32 32" style={{ opacity: op }}>
        <path
          d="M17 4 L9 18 L15 18 L13 28 L23 13 L17 13 Z"
          fill="none"
          stroke={stroke}
          strokeWidth={sw}
          strokeLinejoin="round"
          strokeLinecap="round"
        />
      </svg>
    );
  }
  if (kind === "actor") {
    return (
      <svg width={size} height={size} viewBox="0 0 32 32" style={{ opacity: op }}>
        <rect
          x="6"
          y="6"
          width="20"
          height="20"
          rx="4"
          fill="none"
          stroke={stroke}
          strokeWidth={sw}
        />
        <circle cx="13" cy="14" r="1.6" fill={stroke} />
        <circle cx="19" cy="14" r="1.6" fill={stroke} />
        <path
          d="M12 20 Q16 23 20 20"
          fill="none"
          stroke={stroke}
          strokeWidth={sw}
          strokeLinecap="round"
        />
      </svg>
    );
  }
  return (
    <svg width={size} height={size} viewBox="0 0 32 32" style={{ opacity: op }}>
      <path
        d="M6 10 L26 10 L26 22 L6 22 Z"
        fill="none"
        stroke={stroke}
        strokeWidth={sw}
        strokeLinejoin="round"
      />
      <path
        d="M10 15 L22 15 M10 18 L18 18"
        stroke={stroke}
        strokeWidth={sw}
        strokeLinecap="round"
      />
    </svg>
  );
};

const FlowNodeView: React.FC<{
  node: FlowNode;
  index: number;
  baseDelay: number;
}> = ({ node, index, baseDelay }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const nodeIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay,
    14,
    "ELASTIC"
  );
  const labelIn = staggeredSpring(
    frame,
    vfps,
    index,
    baseDelay + 6,
    14,
    "GENTLE"
  );

  const breathe = ambientDrift(frame, 2, 90 + index * 17, `node-${index}`);

  const sc = interpolate(nodeIn, [0, 1], [0.4, 1]);
  const ringOp = interpolate(nodeIn, [0, 0.8, 1], [0, 0.9, 0.55]);
  const ringSc = interpolate(nodeIn, [0, 1], [0.6, 1.25]);

  const labelY = interpolate(labelIn, [0, 1], [10, 0]);

  const NODE_SIZE = 150;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        position: "relative",
        transform: `translateY(${breathe}px)`,
      }}
    >
      {/* Pulse ring */}
      <div
        style={{
          position: "absolute",
          top: 0,
          width: NODE_SIZE,
          height: NODE_SIZE,
          borderRadius: "50%",
          border: `1.5px solid ${COLORS.orange}`,
          opacity: ringOp * 0.35,
          transform: `scale(${ringSc})`,
          pointerEvents: "none",
        }}
      />

      {/* Node circle */}
      <div
        style={{
          width: NODE_SIZE,
          height: NODE_SIZE,
          borderRadius: "50%",
          background: "rgba(255,255,255,0.04)",
          border: `1.5px solid ${COLORS.border}`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          opacity: nodeIn,
          transform: `scale(${sc})`,
          boxShadow: `0 0 0 1px ${COLORS.orangeTint}, 0 12px 40px rgba(0,0,0,0.4)`,
          position: "relative",
          zIndex: 2,
        }}
      >
        <NodeIcon kind={node.icon} size={64} progress={nodeIn} />
      </div>

      {/* Label */}
      <div
        style={{
          marginTop: 28,
          fontFamily: FONT_MARKETING,
          fontWeight: 600,
          fontSize: 38,
          color: COLORS.text,
          letterSpacing: "-0.015em",
          opacity: labelIn,
          transform: `translateY(${labelY}px)`,
          textAlign: "center",
        }}
      >
        {node.label}
      </div>

      {/* Caption */}
      <div
        style={{
          marginTop: 8,
          fontFamily: FONT_PRIMARY,
          fontWeight: 400,
          fontSize: 20,
          color: COLORS.textMuted,
          letterSpacing: "-0.005em",
          opacity: labelIn * 0.95,
          transform: `translateY(${labelY}px)`,
          textAlign: "center",
          maxWidth: 240,
          lineHeight: 1.35,
        }}
      >
        {node.caption}
      </div>
    </div>
  );
};

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const titleIn = springIn(frame, vfps, 8, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 18, "LIQUID");

  const NODE_BASE_DELAY = 22;

  // Line draws between nodes — two segments.
  const line1Progress = spring({
    frame,
    fps: vfps,
    delay: NODE_BASE_DELAY + 8,
    config: SPRINGS.LIQUID,
  });
  const line2Progress = spring({
    frame,
    fps: vfps,
    delay: NODE_BASE_DELAY + 22,
    config: SPRINGS.LIQUID,
  });

  // Arrowheads pop in as lines finish.
  const arrow1In = springIn(frame, vfps, NODE_BASE_DELAY + 16, "ELASTIC");
  const arrow2In = springIn(frame, vfps, NODE_BASE_DELAY + 30, "ELASTIC");

  const titleY = interpolate(titleIn, [0, 1], [22, 0]);
  const eyebrowY = interpolate(eyebrowIn, [0, 1], [10, 0]);
  const titleScale = interpolate(titleIn, [0, 1], [0.96, 1]);
  const titleBlur = interpolate(titleIn, [0, 1], [6, 0]);

  const flowDrift = ambientDrift(frame, 2, 130, "flow-drift");

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(110% 70% at 50% 35%, ${COLORS.card} 0%, ${COLORS.bg} 65%)`,
        fontFamily: FONT_MARKETING,
      }}
    >
      <Background />

      {/* Eyebrow — top-left */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "12%",
          opacity: eyebrowIn,
          transform: `translateY(${eyebrowY}px)`,
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        / how it works
      </div>

      {/* Headline — left aligned, upper third */}
      <div
        style={{
          position: "absolute",
          left: "8%",
          top: "20%",
          maxWidth: "70%",
          fontFamily: FONT_MARKETING,
          fontWeight: 600,
          fontSize: 88,
          color: COLORS.text,
          lineHeight: 1.02,
          letterSpacing: "-0.025em",
          opacity: titleIn,
          transform: `translateY(${titleY}px) scale(${titleScale})`,
          filter: `blur(${titleBlur}px)`,
        }}
      >
        One pipeline.{" "}
        <span
          style={{
            background: COLORS.orangeTint,
            borderBottom: `3px solid ${COLORS.orange}`,
            padding: "0 12px",
            borderRadius: 8,
            color: COLORS.text,
            clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            display: "inline-block",
          }}
        >
          Any trigger.
        </span>
      </div>

      {/* Flow diagram — vertically centered lower half */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: "62%",
          transform: `translateY(-50%) translateY(${flowDrift}px)`,
          display: "flex",
          justifyContent: "center",
          alignItems: "flex-start",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "flex-start",
            gap: 0,
            width: "82%",
            maxWidth: 1500,
            justifyContent: "space-between",
            position: "relative",
          }}
        >
          {/* Node 1 */}
          <div style={{ width: 280, display: "flex", justifyContent: "center" }}>
            <FlowNodeView node={NODES[0]} index={0} baseDelay={NODE_BASE_DELAY} />
          </div>

          {/* Connector 1 — between node 1 and 2 */}
          <div
            style={{
              flex: 1,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              marginTop: 75,
              position: "relative",
              height: 0,
            }}
          >
            <div
              style={{
                width: "100%",
                height: 1.5,
                background: `linear-gradient(90deg, ${COLORS.orange} 0%, ${COLORS.orange} ${line1Progress * 100}%, ${COLORS.border} ${line1Progress * 100}%, ${COLORS.border} 100%)`,
              }}
            />
            {/* Arrowhead 1 */}
            <div
              style={{
                position: "absolute",
                right: -2,
                top: "50%",
                transform: `translateY(-50%) scale(${arrow1In})`,
                opacity: arrow1In,
              }}
            >
              <svg width={18} height={18} viewBox="0 0 18 18">
                <path
                  d="M2 4 L14 9 L2 14 Z"
                  fill={COLORS.orange}
                />
              </svg>
            </div>
          </div>

          {/* Node 2 */}
          <div style={{ width: 280, display: "flex", justifyContent: "center" }}>
            <FlowNodeView node={NODES[1]} index={1} baseDelay={NODE_BASE_DELAY} />
          </div>

          {/* Connector 2 — between node 2 and 3 */}
          <div
            style={{
              flex: 1,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              marginTop: 75,
              position: "relative",
              height: 0,
            }}
          >
            <div
              style={{
                width: "100%",
                height: 1.5,
                background: `linear-gradient(90deg, ${COLORS.orange} 0%, ${COLORS.orange} ${line2Progress * 100}%, ${COLORS.border} ${line2Progress * 100}%, ${COLORS.border} 100%)`,
              }}
            />
            {/* Arrowhead 2 */}
            <div
              style={{
                position: "absolute",
                right: -2,
                top: "50%",
                transform: `translateY(-50%) scale(${arrow2In})`,
                opacity: arrow2In,
              }}
            >
              <svg width={18} height={18} viewBox="0 0 18 18">
                <path
                  d="M2 4 L14 9 L2 14 Z"
                  fill={COLORS.orange}
                />
              </svg>
            </div>
          </div>

          {/* Node 3 */}
          <div style={{ width: 280, display: "flex", justifyContent: "center" }}>
            <FlowNodeView node={NODES[2]} index={2} baseDelay={NODE_BASE_DELAY} />
          </div>
        </div>
      </div>

      {/* Subtle dot field — bottom-left */}
      <div
        style={{
          position: "absolute",
          left: "4%",
          bottom: "6%",
          width: 220,
          height: 90,
          opacity: 0.32,
          backgroundImage: `radial-gradient(${COLORS.orange} 1.2px, transparent 1.5px)`,
          backgroundSize: "12px 12px",
          maskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.85), transparent)",
          WebkitMaskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.85), transparent)",
        }}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// SCENE 3: Tagline — "Build. Run. Scale." (lingers 5s longer)
// ============================================================
// 60 frames original + 125 extra frames (5s @ 25fps) = 185 frames
const SCENE_THREE_DURATION = 185;

const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const WORDS = ["Build.", "Run.", "Scale."];

  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const subIn = springIn(frame, vfps, 38, "GENTLE");

  const eyebrowY = interpolate(eyebrowIn, [0, 1], [10, 0]);
  const subY = interpolate(subIn, [0, 1], [14, 0]);

  const driftY = ambientDrift(frame, 2, 100, "tagline-y");

  // Extra ambient breath on the tagline column for the long linger
  const lingerBreath = ambientDrift(frame, 1.2, 160, "linger-breath");

  return (
    <AbsoluteFill
      style={{
        background: `radial-gradient(110% 80% at 30% 60%, ${COLORS.card} 0%, ${COLORS.bg} 65%)`,
        fontFamily: FONT_MARKETING,
      }}
    >
      <Background />

      {/* Eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "22%",
          opacity: eyebrowIn,
          transform: `translateY(${eyebrowY}px)`,
          fontFamily: "monospace",
          fontSize: 22,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        / actors
      </div>

      {/* Tagline — word by word, left anchored */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "32%",
          maxWidth: "85%",
          display: "flex",
          flexWrap: "wrap",
          gap: 28,
          alignItems: "baseline",
          transform: `translateY(${driftY + lingerBreath}px)`,
        }}
      >
        {WORDS.map((word, i) => {
          const wIn = springIn(frame, vfps, 10 + i * 12, "SNAPPY");
          const wY = interpolate(wIn, [0, 1], [56, 0]);
          const wSc = interpolate(wIn, [0, 1], [0.9, 1]);
          const wBl = interpolate(wIn, [0, 1], [10, 0]);

          const isLast = i === WORDS.length - 1;

          return (
            <span
              key={i}
              style={{
                fontFamily: FONT_MARKETING,
                fontSize: 220,
                fontWeight: 600,
                color: isLast ? COLORS.text : COLORS.text,
                lineHeight: 0.95,
                letterSpacing: "-0.04em",
                opacity: wIn,
                transform: `translateY(${wY}px) scale(${wSc})`,
                filter: `blur(${wBl}px)`,
                display: "inline-block",
                position: "relative",
              }}
            >
              {isLast ? (
                <span
                  style={{
                    background: COLORS.orangeTint,
                    borderBottom: `5px solid ${COLORS.orange}`,
                    padding: "0 18px",
                    borderRadius: 12,
                  }}
                >
                  {word}
                </span>
              ) : (
                word
              )}
            </span>
          );
        })}
      </div>

      {/* Subhead */}
      <div
        style={{
          position: "absolute",
          left: "9%",
          top: "70%",
          maxWidth: 760,
          fontFamily: FONT_PRIMARY,
          fontWeight: 400,
          fontSize: 34,
          color: COLORS.textMuted,
          lineHeight: 1.35,
          letterSpacing: "-0.005em",
          opacity: subIn,
          transform: `translateY(${subY}px)`,
        }}
      >
        The agent runtime that ships with you.
      </div>

      {/* Decorative dot field — right edge */}
      <div
        style={{
          position: "absolute",
          right: "5%",
          top: "30%",
          width: 320,
          height: 320,
          opacity: 0.4,
          backgroundImage: `radial-gradient(${COLORS.orange} 1.4px, transparent 1.7px)`,
          backgroundSize: "16px 16px",
          maskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.95), transparent)",
          WebkitMaskImage:
            "radial-gradient(closest-side, rgba(0,0,0,0.95), transparent)",
          transform: `translateY(${ambientDrift(frame, 3, 140, "right-dots")}px)`,
        }}
      />
    </AbsoluteFill>
  );
};

// ============================================================
// Main composition
// ============================================================
export const durationInFrames =
  SCENE_ONE_DURATION + SCENE_TWO_DURATION + SCENE_THREE_DURATION - 2 * TRANSITION;

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_ONE_DURATION + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_TWO_DURATION + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_THREE_DURATION}>
        <SceneThree />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
